# Python 3.14 t-strings: write a custom renderer that uppercases interpolations
from string.templatelib import Interpolation, Template

def lower_upper(template: Template) -> str:
    """Render static parts lowercased and interpolations uppercased."""
    parts: list[str] = []
    for item in template:
        if isinstance(item, Interpolation):
            parts.append(str(item.value).upper())
        else:
            parts.append(item.lower())
    return "".join(parts)

name = "world"
assert lower_upper(t"HELLO {name}") == "hello WORLD"

# Python 3.14 t-strings: render a template like an f-string with a custom f() function
from string.templatelib import Interpolation, Template
from typing import Literal

def convert(value: object, conversion: Literal["a", "r", "s"] | None) -> object:
    if conversion == "a":
        return ascii(value)
    if conversion == "r":
        return repr(value)
    if conversion == "s":
        return str(value)
    return value

def f(template: Template) -> str:
    parts: list[str] = []
    for item in template:
        match item:
            case str() as s:
                parts.append(s)
            case Interpolation(value, _, conversion, format_spec):
                parts.append(format(convert(value, conversion), format_spec))
    return "".join(parts)

name = "World"
value = 42
assert f(t"Hello {name!r}, value: {value:.2f}") == "Hello 'World', value: 42.00"

# Python 3.14 t-strings: render HTML with automatic escaping of interpolated values
import html as _html
from string.templatelib import Interpolation, Template

def html(template: Template) -> str:
    parts: list[str] = []
    for item in template:
        if isinstance(item, Interpolation):
            parts.append(_html.escape(str(item.value)))
        else:
            parts.append(item)
    return "".join(parts)

evil = "<script>alert('evil')</script>"
assert html(t"<p>{evil}</p>") == "<p>&lt;script&gt;alert(&#x27;evil&#x27;)&lt;/script&gt;</p>"
